import{_ as o,C as e,o as r,c as s,ae as n,E as l}from"./chunks/framework.B6gjLfeO.js";const m=JSON.parse('{"title":"주요 기능","description":"","frontmatter":{},"headers":[],"relativePath":"ko/features.md","filePath":"ko/features.md"}'),u={name:"ko/features.md"};function _(c,a,h,d,p,b){const i=e("ApiMatrix"),t=e("PluginShowcase");return r(),s("div",null,[a[0]||(a[0]=n('<h1 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h1><p>OTools는 “도구 통합, 플러그인 생태계, Tabs 멀티태스킹”을 하나의 고성능 데스크톱 플랫폼으로 통합합니다. 아래는 핵심 기능 개요입니다.</p><h2 id="_1-tabs-멀티태스킹" tabindex="-1">1. Tabs 멀티태스킹 <a class="header-anchor" href="#_1-tabs-멀티태스킹" aria-label="Permalink to &quot;1. Tabs 멀티태스킹&quot;">​</a></h2><ul><li>여러 도구를 동시에 열어 컨텍스트를 유지합니다.</li><li>플러그인 간 빠른 전환으로 재로딩이 필요 없습니다.</li><li>생산성 워크플로에 최적화되어 창 전환 비용을 줄입니다.</li></ul><h2 id="_2-해양-생태계-플러그인-시스템" tabindex="-1">2. 해양 생태계 플러그인 시스템 <a class="header-anchor" href="#_2-해양-생태계-플러그인-시스템" aria-label="Permalink to &quot;2. 해양 생태계 플러그인 시스템&quot;">​</a></h2><ul><li>내장 도구 + 커뮤니티 플러그인이 완전한 생태계를 구성합니다.</li><li>핫 업데이트, 버전 기록, 마켓 배포 지원.</li><li>통합 플러그인 디렉터리와 관리 진입점을 제공합니다.</li></ul><h2 id="_3-고성능-데스크톱-런타임" tabindex="-1">3. 고성능 데스크톱 런타임 <a class="header-anchor" href="#_3-고성능-데스크톱-런타임" aria-label="Permalink to &quot;3. 고성능 데스크톱 런타임&quot;">​</a></h2><ul><li>로컬 기능 호출로 빠르고 안정적입니다.</li><li>Native 동적 라이브러리로 성능 상한을 확장합니다.</li><li>통합 API 브리지를 통해 호출 방식이 일관됩니다.</li></ul><h2 id="_4-개발자-친화적" tabindex="-1">4. 개발자 친화적 <a class="header-anchor" href="#_4-개발자-친화적" aria-label="Permalink to &quot;4. 개발자 친화적&quot;">​</a></h2><ul><li>개발자 센터에서 생성, 바인딩, 디버깅까지 한 번에.</li><li>Web/Vue 스캐폴딩과 Rust 네이티브 프로젝트를 원클릭으로 생성.</li><li>마켓 배포를 위한 패키징 프로세스 제공.</li></ul><h2 id="_5-내장-모듈" tabindex="-1">5. 내장 모듈 <a class="header-anchor" href="#_5-내장-모듈" aria-label="Permalink to &quot;5. 내장 모듈&quot;">​</a></h2><ul><li>Git 프로젝트 관리 및 AI 보조 문서</li><li>HTTP / MQTT / FTP 네트워크 도구</li><li>Docker 및 SSH/SFTP 터미널</li><li>데이터베이스 관리(DBM)</li><li>패킷 캡처 및 재생(Pakcap)</li><li>스크린샷, 오디오, 디스크 유틸리티 등</li></ul>',12)),l(i),l(t)])}const P=o(u,[["render",_]]);export{m as __pageData,P as default};
